// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/jobs", wrapper.ListJobs)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/jobs/{id}", wrapper.GetJob)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/jobs/{id}/stages", wrapper.ListJobStages)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/candidates", wrapper.ListCandidates)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/candidates/{id}", wrapper.GetCandidate)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/candidates/{id}/activity_feed", wrapper.GetActivityFeed)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/candidates/{id}/activity_feed/notes", wrapper.CreateCandidateNote)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/applications", wrapper.ListApplications)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/applications/{id}", wrapper.GetApplication)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/applications/{id}/offers", wrapper.ListApplicationOffers)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/applications/{id}/scorecards", wrapper.ListApplicationScorecards)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/offers", wrapper.ListOffers)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/offers/{id}", wrapper.GetOffer)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/scorecards", wrapper.ListScorecards)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/users", wrapper.ListUsers)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/users/{id}", wrapper.GetUser)

	return m
}

